//! Razer mice. The protocol is in `docs/protocols/razer-mice.md`, written from facts found in
//! OpenRazer (GPL-2.0): no code was copied. The table in `razer_models.rs` is generated by
//! `tools/openrazer_facts.py`. None has been tried with PeriHub.
//!
//! OpenRazer always sends the DPI with "variable storage", which keeps it in the mouse's memory,
//! so every change PeriHub makes is treated as one that stays: No warranty box, backup, read-back
//! and undo.

use std::time::Duration;

use super::task::Driver;
use super::{Command, DpiLimits, Effect, Io, Limits, Reading, Settings};
use crate::error::{Error, Result};

const REPORT: usize = 90;
const STATUS_OK: u8 = 0x02;
const STATUS_BUSY: u8 = 0x01;
const NOSTORE: u8 = 0x00;
const VARSTORE: u8 = 0x01;
const DPI_MIN: u16 = 100;
const DPI_STEP: u16 = 50;

/// (class, id) of the commands, at bytes 6 and 7 of the report.
const GET_FIRMWARE: [u8; 2] = [0x00, 0x81];
const GET_DPI: [u8; 2] = [0x04, 0x85];
const SET_DPI: [u8; 2] = [0x04, 0x05];
const GET_POLLING: [u8; 2] = [0x00, 0x85];
const SET_POLLING: [u8; 2] = [0x00, 0x05];

/// Everything PeriHub may send to a Razer mouse, by class and command at byte 6. Lighting,
/// device mode, macros and every other command are left out.
pub const COMMANDS: &[Command] = &[
    Command { prefix: &GET_FIRMWARE, at: 6, effect: Effect::Read, name: "read firmware" },
    Command { prefix: &GET_DPI, at: 6, effect: Effect::Read, name: "read DPI" },
    Command { prefix: &GET_POLLING, at: 6, effect: Effect::Read, name: "read polling rate" },
    Command { prefix: &SET_DPI, at: 6, effect: Effect::Save, name: "set DPI (stored)" },
    Command { prefix: &SET_POLLING, at: 6, effect: Effect::Save, name: "set polling rate" },
];

/// Polling rate codes of the standard command.
const POLLING: [(u8, u16); 3] = [(0x01, 1000), (0x02, 500), (0x08, 125)];

/// The transaction id each command needs on a model; `None`: PeriHub does not send it there.
#[derive(Debug, Clone, Copy)]
pub struct Tid {
    pub firmware: Option<u8>,
    pub dpi_get: Option<u8>,
    pub dpi_set: Option<u8>,
    pub poll_get: Option<u8>,
    pub poll_set: Option<u8>,
}

#[derive(Debug, Clone, Copy)]
pub struct Params {
    /// How long the mouse needs before its answer can be read.
    pub wait_us: u32,
    /// 0: unknown, the DPI is not changed.
    pub dpi_max: u16,
    pub tid: Tid,
    /// The DPI is read from the stored settings (a few old mice).
    pub dpi_read_stored: bool,
}

/// A request: status, transaction id, remaining packets, protocol, size, class, command, arguments,
/// then the checksum (XOR of bytes 2 to 87) and a reserved byte.
pub fn request(tid: u8, command: [u8; 2], size: u8, args: &[u8]) -> [u8; REPORT] {
    let mut r = [0u8; REPORT];
    r[1] = tid;
    r[5] = size;
    r[6] = command[0];
    r[7] = command[1];
    r[8..8 + args.len()].copy_from_slice(args);
    r[88] = r[2..88].iter().fold(0, |crc, b| crc ^ b);
    r
}

pub struct Razer {
    p: Params,
}

impl Razer {
    pub fn new(p: Params) -> Self {
        Self { p }
    }

    /// Sends a request and returns the answer's arguments, after checking that the answer is for
    /// this request and that the mouse carried it out.
    fn query(&self, io: &mut Io, tid: u8, command: [u8; 2], size: u8, args: &[u8]) -> Result<[u8; 80]> {
        let req = request(tid, command, size, args);
        let wait = Duration::from_micros(self.p.wait_us.max(600) as u64) + Duration::from_millis(2);
        let answer = io.feature_query(&req, wait, |a| a[0] != STATUS_BUSY)?;
        if answer[2..4] != req[2..4] || answer[6..8] != req[6..8] {
            return Err(Error::Protocol(format!("the answer is not for this request: {}", super::hex(&answer[..8]))));
        }
        match answer[0] {
            STATUS_OK => Ok(answer[8..88].try_into().unwrap()),
            0x05 => Err(Error::Invalid("the mouse does not support this command".into())),
            status => Err(Error::Protocol(format!("the mouse answered with status {status:02x}"))),
        }
    }
}

impl Driver for Razer {
    fn commands(&self) -> Vec<Command> {
        COMMANDS.to_vec()
    }

    fn source(&self) -> &'static str {
        "OpenRazer (facts only)"
    }

    fn profiles(&self) -> u8 {
        1
    }

    fn can_save(&self) -> bool {
        false
    }

    fn changes_stay(&self) -> bool {
        true
    }

    fn read(&mut self, io: &mut Io) -> Result<Reading> {
        let mut problems = Vec::new();
        let tid = self.p.tid;
        let firmware = match tid.firmware {
            Some(t) => Some(self.query(io, t, GET_FIRMWARE, 0x02, &[]).map(|a| format!("v{}.{}", a[0], a[1]))?),
            None => None,
        };
        let mut settings = Settings::default();
        let mut limits = Limits::default();
        if let Some(t) = tid.dpi_get {
            let store = if self.p.dpi_read_stored { VARSTORE } else { NOSTORE };
            let a = self.query(io, t, GET_DPI, 0x07, &[store])?;
            let (x, y) = (u16::from_be_bytes([a[1], a[2]]), u16::from_be_bytes([a[3], a[4]]));
            let max = if self.p.dpi_max > 0 { self.p.dpi_max } else { 45000 };
            for d in [x, y] {
                if !(DPI_MIN..=max).contains(&d) {
                    problems.push(format!("DPI {d}, outside {DPI_MIN}–{max}"));
                }
            }
            settings.dpi_levels = vec![x];
            // Different X and Y DPI are shown as X and not changed.
            if tid.dpi_set == tid.dpi_get && self.p.dpi_max > 0 && x == y {
                limits.dpi = Some(DpiLimits { min: DPI_MIN, max: self.p.dpi_max, step: DPI_STEP });
            }
        }
        if let Some(t) = tid.poll_get {
            let a = self.query(io, t, GET_POLLING, 0x01, &[])?;
            match POLLING.iter().find(|(code, _)| *code == a[0]) {
                Some((_, hz)) => settings.polling_hz = Some(*hz),
                None => problems.push(format!("polling rate code {:02x}", a[0])),
            }
            if tid.poll_set == tid.poll_get {
                limits.polling_hz = POLLING.iter().map(|(_, hz)| *hz).collect();
                limits.polling_hz.sort_unstable();
            }
        }
        Ok(Reading {
            firmware,
            settings,
            limits,
            problem: (!problems.is_empty()).then(|| format!("unexpected answer: {}", problems.join(", "))),
            ..Default::default()
        })
    }

    fn apply(&mut self, io: &mut Io, from: &Settings, to: &Settings) -> Result<()> {
        if to.dpi_levels != from.dpi_levels {
            let (t, dpi) = (self.p.tid.dpi_set, to.dpi_levels.first().copied());
            let (Some(t), Some(dpi)) = (t, dpi) else { return Err(Error::Invalid("DPI".into())) };
            let [hi, lo] = dpi.to_be_bytes();
            // As OpenRazer sends it: stored, the same DPI for X and Y.
            self.query(io, t, SET_DPI, 0x07, &[VARSTORE, hi, lo, hi, lo, 0, 0])?;
        }
        if to.polling_hz != from.polling_hz {
            let t = self.p.tid.poll_set.ok_or_else(|| Error::Invalid("polling rate".into()))?;
            let code = POLLING
                .iter()
                .find(|(_, hz)| Some(*hz) == to.polling_hz)
                .map(|(c, _)| *c)
                .ok_or_else(|| Error::Invalid("polling rate".into()))?;
            self.query(io, t, SET_POLLING, 0x01, &[code])?;
        }
        Ok(())
    }

    fn save(&mut self, _io: &mut Io) -> Result<()> {
        Err(Error::Invalid("Razer mice store every change by themselves".into()))
    }
}

#[cfg(test)]
mod tests {
    use std::sync::{Arc, Mutex};

    use super::super::fake::FakeHid;
    use super::super::task::start_for_test;
    use super::super::{Model, Protocol, find, models};
    use super::*;

    /// DPI, polling code, and every request received.
    type Mouse = Arc<Mutex<(u16, u8, Vec<Vec<u8>>)>>;

    fn deathadder_v2() -> &'static Model {
        find(0x1532, 0x0084).unwrap()
    }

    /// A simulated DeathAdder V2: answers feature requests, keeps its DPI and polling rate.
    fn fake(state: Mouse, echo_wrong: bool) -> FakeHid {
        let hid = FakeHid::new(|_| Vec::new());
        let s = state.clone();
        hid.0.lock().unwrap().on_feature = Some(Box::new(move |req: &[u8]| {
            let mut st = s.lock().unwrap();
            st.2.push(req.to_vec());
            let mut a = req.to_vec();
            a[0] = STATUS_OK;
            match [req[6], req[7]] {
                GET_FIRMWARE => a[8..10].copy_from_slice(&[1, 4]),
                GET_DPI => {
                    a[9..11].copy_from_slice(&st.0.to_be_bytes());
                    a[11..13].copy_from_slice(&st.0.to_be_bytes());
                }
                GET_POLLING => a[8] = st.1,
                SET_DPI => st.0 = u16::from_be_bytes([req[9], req[10]]),
                SET_POLLING => st.1 = req[8],
                _ => a[0] = 0x05,
            }
            if echo_wrong {
                a[7] ^= 0x80;
            }
            a
        }));
        hid
    }

    fn temp(name: &str) -> std::path::PathBuf {
        let root = std::env::temp_dir().join(format!("perihub-test-razer-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        root
    }

    #[test]
    fn requests_carry_the_checksum_openrazer_documents() {
        let r = request(0x3F, GET_DPI, 0x07, &[NOSTORE]);
        assert_eq!(r[..9], [0x00, 0x3F, 0x00, 0x00, 0x00, 0x07, 0x04, 0x85, 0x00]);
        assert_eq!(r[88], 0x07 ^ 0x04 ^ 0x85);
        assert_eq!(r.len(), 90);
    }

    #[test]
    fn the_table_is_consistent() {
        let mut ids: Vec<u16> = Vec::new();
        for m in models().filter(|m| m.vendor_id == 0x1532) {
            let Protocol::Razer(p) = m.protocol else { panic!("{}", m.name) };
            assert!(matches!(m.interface, Some(0) | Some(3)), "{}", m.name);
            if p.tid.dpi_set.is_some() {
                assert_eq!(p.tid.dpi_set, p.tid.dpi_get, "{}", m.name);
            }
            assert!(!m.name.contains("Receiver") && !m.name.contains("Dock"), "{}", m.name);
            ids.extend(m.product_ids);
        }
        let n = ids.len();
        ids.sort_unstable();
        ids.dedup();
        assert_eq!(ids.len(), n);
        assert!(n >= 60, "{n} mice");
    }

    #[test]
    fn a_deathadder_v2_reads_as_documented_and_only_reads() {
        let state = Arc::new(Mutex::new((800u16, 0x01u8, Vec::new())));
        let task =
            start_for_test(Box::new(fake(state.clone(), false)), deathadder_v2(), 0x0084, false, temp("read")).unwrap();
        assert_eq!(task.info.firmware.as_deref(), Some("v1.4"));
        assert_eq!(task.info.settings.dpi_levels, [800]);
        assert_eq!(task.info.settings.polling_hz, Some(1000));
        assert!(task.info.changes_stay && !task.info.can_save);
        let sent = &state.lock().unwrap().2;
        assert!(sent.iter().all(|r| r[1] == 0x3F && r[7] & 0x80 != 0), "reads with transaction id 3f only");
    }

    #[test]
    fn a_dpi_change_is_stored_read_back_and_undone_unless_kept() {
        let state = Arc::new(Mutex::new((800u16, 0x01u8, Vec::new())));
        let mut task =
            start_for_test(Box::new(fake(state.clone(), false)), deathadder_v2(), 0x0084, true, temp("change"))
                .unwrap();
        let mut wanted = task.info.settings.clone();
        wanted.dpi_levels = vec![1600];
        wanted.polling_hz = Some(500);
        task.change(&wanted, false, None).unwrap();
        let now = |s: &Mouse| {
            let s = s.lock().unwrap();
            (s.0, s.1)
        };
        assert_eq!(now(&state), (1600, 0x02));
        let set = state.lock().unwrap().2.iter().find(|r| r[6..8] == SET_DPI).unwrap().clone();
        assert_eq!(set[8..15], [VARSTORE, 0x06, 0x40, 0x06, 0x40, 0, 0]);
        task.expire_undo();
        crate::worker::DeviceTask::tick(&mut task).unwrap();
        assert_eq!(now(&state), (800, 0x01), "back to 800 DPI and 1000 Hz");
        let _ = std::fs::remove_dir_all(task.backups());
    }

    #[test]
    fn an_answer_for_another_command_is_refused() {
        let state = Arc::new(Mutex::new((800u16, 0x01u8, Vec::new())));
        let result = start_for_test(Box::new(fake(state, true)), deathadder_v2(), 0x0084, true, temp("echo"));
        assert!(matches!(result, Err(Error::Protocol(_))));
    }

    #[test]
    fn values_the_mouse_does_not_take_are_refused() {
        let state = Arc::new(Mutex::new((800u16, 0x01u8, Vec::new())));
        let mut task =
            start_for_test(Box::new(fake(state.clone(), false)), deathadder_v2(), 0x0084, true, temp("refuse"))
                .unwrap();
        for dpi in [50, 20050, 825] {
            let mut wanted = task.info.settings.clone();
            wanted.dpi_levels = vec![dpi];
            assert!(task.change(&wanted, false, None).is_err(), "{dpi}");
        }
        assert!(state.lock().unwrap().2.iter().all(|r| r[7] & 0x80 != 0), "nothing but reads");
        let _ = std::fs::remove_dir_all(task.backups());
    }

    #[test]
    fn commands_outside_the_list_never_leave() {
        let state = Arc::new(Mutex::new((800u16, 0x01u8, Vec::new())));
        let mut io = Io::new(Box::new(fake(state.clone(), false)), COMMANDS.to_vec(), true);
        for command in [[0x00, 0x04], [0x03, 0x0A], [0x0F, 0x02], [0x00, 0x86]] {
            let req = request(0x3F, command, 0x02, &[]);
            assert!(io.feature_query(&req, Duration::ZERO, |_| true).is_err(), "{command:02x?}");
        }
        assert!(state.lock().unwrap().2.is_empty());
    }
}
